\item[S1] ULAM.AI and the UnsolvedMath Contributors, UnsolvedMath: A Curated Collection of Open Mathematics Problems, record 2302070 (AMR-022-2070). CC BY 4.0. \url{https://huggingface.co/datasets/ulamai/UnsolvedMath}.
\item[S2] W. K. Hayman and E. F. Lingham, \emph{Research Problems in Function Theory}, arXiv:1809.07200v2 (2018), Problem 2.70 and Update 2.70. \url{https://arxiv.org/abs/1809.07200}.
\end{description}
